export const TEAM_INVITE_EMAIL_QUEUE = "team-invitation-email";
export const SEND_TEAM_INVITE_JOB = "send-team-invite";

/**
 * The queue payload deliberately contains ONLY the invitation id. The raw
 * token is generated by the worker so it can never reach Redis or a log.
 */
export interface InvitationEmailJob {
  invitationId: string;
}

export interface IInvitationDeliveryQueue {
  enqueue(job: InvitationEmailJob): Promise<void>;
}
